// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }
    function testFuzz_property(address newOwner) public {
        // admin is the deployer (this test contract); keep domain wide
        address current = c.owner();
        vm.assume(newOwner != current); // require an actual change of ownership
        vm.prank(address(this)); // deployer == admin, allowed by onlyAdmin
        bool ok = c.setOwner(newOwner);
        // General rule: every admissible setOwner call persists the new owner.
        assertTrue(ok && c.owner() == newOwner, "setOwner must persist the new owner");
    }
}
